INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: File Penting Terlanjur Terhapus$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Jari terpeleset menekan Delete, atau folder dibersihkan terburu-buru — tiba-tiba dokumen penting hilang. Kepanikan membuat banyak orang langsung menyalahkan diri sendiri, padahal di Windows file yang dihapus biasanya belum benar-benar musnah. Ia hanya dipindahkan ke Recycle Bin, tempat penampungan sementara sebelum dihapus permanen.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Cara Kerja Recycle Bin$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Recycle Bin adalah folder khusus yang menampung file dan folder yang dihapus dari hard disk internal. Selama file masih ada di dalamnya, ia bisa dikembalikan ke lokasi semula dengan utuh. Namun ada pengecualian: file yang dihapus dengan Shift+Delete, file dari flashdisk atau kartu memori, serta file yang melebihi kapasitas Recycle Bin akan dilewati dan langsung hilang permanen.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat yang Dibutuhkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Komputer Windows 10 atau 11$txt$, $txt$Ikon Recycle Bin di desktop (atau akses lewat File Explorer)$txt$, $txt$Kabel listrik stabil — jangan matikan paksa komputer saat proses pemulihan$txt$, $txt$Opsional: software pemulihan data bila Recycle Bin sudah dikosongkan$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah-langkah Memulihkan File$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Buka Recycle Bin lewat ikon desktop, atau ketik 'Recycle Bin' di bilah alamat File Explorer$txt$, $txt$Gunakan kolom pencarian untuk menemukan file yang hilang$txt$, $txt$Klik kanan file lalu pilih 'Restore' — file kembali ke folder semula$txt$, $txt$Untuk banyak file: tahan Ctrl sambil mengklik tiap file, lalu Restore$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Jika Recycle Bin Sudah Dikosongkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Segera hentikan aktivitas menulis data baru ke drive tersebut — semakin banyak data baru ditulis, semakin kecil peluang file lama bisa diselamatkan. Gunakan software pemulihan data seperti Recuva: instal di drive lain, jalankan pemindaian pada drive yang bersangkutan, lalu pulihkan file yang ditemukan ke lokasi berbeda. Keberhasilan tidak dijamin 100 persen, tetapi peluangnya jauh lebih besar jika bertindak cepat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Risiko dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Unduh software pemulihan hanya dari situs resmi — versi bajakan bisa membawa malware$txt$, $txt$Jangan instal software pemulihan di drive yang sama dengan file yang hilang$txt$, $txt$Aktifkan backup rutin: File History Windows atau salinan ke cloud (Google Drive/OneDrive)$txt$, $txt$Hindari Shift+Delete kecuali benar-benar yakin, agar file selalu mampir dulu ke Recycle Bin$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Punggung Terasa Kaku Setiap Pagi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Bangun tidur dengan punggung terasa kaku, atau setelah duduk berjam-jam di depan komputer badan terasa seperti papan. Kondisi ini umum dialami pekerja kantoran dan pelajar. Otot-otot punggung yang lama tidak digerakkan menjadi tegang dan kaku, sehingga gerakan sederhana pun terasa tidak nyaman.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Mengapa Punggung Menjadi Kaku$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Otot punggung menopang tulang belakang sepanjang hari. Duduk membungkuk, kasur yang terlalu empuk atau terlalu keras, serta jarang bergerak membuat otot memendek dan aliran darah berkurang. Peregangan ringan membantu mengembalikan kelenturan otot dan melancarkan peredaran darah. Catatan: artikel ini berisi informasi umum dan bukan pengganti nasihat medis profesional.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Persiapan Sebelum Peregangan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Matras atau alas empuk di lantai$txt$, $txt$Pakaian longgar yang nyaman$txt$, $txt$Ruangan dengan sirkulasi udara baik$txt$, $txt$Waktu 10-15 menit tanpa gangguan$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Gerakan Peregangan Harian$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Kucing-sapi (cat-cow): posisi merangkak, lengkungkan punggung ke bawah saat tarik napas dan ke atas saat buang napas, ulangi 8-10 kali perlahan$txt$, $txt$Child's pose: dudukkan bokong ke tumit, luruskan tangan ke depan hingga dahi menyentuh lantai, tahan 20-30 detik, ulangi 3 kali$txt$, $txt$Putaran berbaring: telentang, lutut ditekuk, jatuhkan lutut ke kanan sambil kepala menoleh ke kiri, tahan 20 detik, ganti sisi, 3 kali tiap sisi$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kapan Harus ke Dokter$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Hentikan peregangan jika timbul nyeri tajam, kesemutan, atau mati rasa$txt$, $txt$Jangan memaksakan gerakan hingga berbunyi 'krek' dengan paksa$txt$, $txt$Segera konsultasi dokter jika kaku disertai demam, nyeri menjalar ke kaki, atau gangguan buang air$txt$, $txt$Penderita hernia tulang belakang (HNP) atau osteoporosis sebaiknya berkonsultasi dulu sebelum rutin peregangan$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil dan Kebiasaan Lanjutan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Setelah rutin 1-2 minggu, punggung seharusnya terasa lebih lentur saat bangun pagi dan duduk lama. Sebagai tindak lanjut, terapkan aturan 30 menit: berdiri dan bergerak ringan setiap 30 menit duduk. Perbaiki juga postur duduk — punggung tegak menempel sandaran, layar sejajar mata, dan kaki menapak lantai.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Siapa Suku Dayak Kenyah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Suku Dayak Kenyah adalah salah satu sub-suku Dayak yang mendiami pedalaman Kalimantan Timur dan Kalimantan Utara, terutama di sepanjang Sungai Kayan dan Mahakam. Mereka dikenal sebagai petani ladang berpindah, pengukir ulung, dan pemilik tradisi lisan yang kaya. Salah satu tradisi paling ikonik mereka adalah Hudoq — ritual topeng raksasa yang digelar untuk menyambut musim tanam dan panen.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Hudoq$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Hudoq adalah tarian ritual dengan penari memakai topeng kayu besar dan kostum dari daun pisang, daun kelapa, serta kulit kayu yang menutupi seluruh tubuh. Topeng Hudoq melambangkan roh-roh penjaga padi dan alam. Menurut kepercayaan Dayak Kenyah, Hudoq turun dari kayangan untuk memberkati ladang agar panen melimpah dan desa terhindar dari malapetaka.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Jalannya Ritual Hudoq$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Ritual dimulai dengan sesepuh adat memimpin doa dan sesaji di lamin (rumah panjang). Para penari Hudoq kemudian keluar satu per satu dengan gerakan melompat-lompat mengikuti iringan gendang dan gong. Penonton — terutama anak-anak — akan berlari menghindari 'kejaran' Hudoq karena dipercaya disentuh Hudoq membawa berkah. Puncak acara adalah tarian massal seluruh penari mengelilingi desa sebagai simbol perlindungan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Makna di Balik Topeng Raksasa$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Hudoq bukan sekadar pertunjukan. Ia adalah doa kolektif yang menghubungkan manusia, alam, dan roh leluhur. Topeng yang menakutkan justru melambangkan kekuatan pelindung, bukan kejahatan. Filosofinya: alam akan memberi jika manusia menghormatinya — menebang secukupnya, menanam kembali, dan tidak merusak sungai. Nilai ini sangat relevan di tengah isu deforestasi Kalimantan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Hudoq di Era Modern$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Kini Hudoq juga digelar sebagai festival budaya, misalnya Hudoq Pekayang di Mahakam Ulu yang menarik wisatawan. Di satu sisi ini membantu ekonomi dan pelestarian, di sisi lain muncul kekhawatiran komersialisasi mengikis kesakralan. Para tetua adat menyiasatinya dengan tetap membedakan Hudoq ritual (sakral, tertutup) dan Hudoq festival (terbuka untuk umum) — sebuah kompromi bijak antara pelestarian dan modernitas.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Mengenal Unsur Seng$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Seng (simbol Zn, nomor atom 30) adalah logam berwarna keperakan kebiruan yang relatif lunak. Ia ditemukan sebagai unsur bebas? Tidak — di alam seng selalu bersenyawa, terutama sebagai sfalerit (ZnS). Seng termasuk logam transisi yang unik: meski segolongan dengan tembaga dalam tabel periodik, ia jauh lebih reaktif dan justru reaktivitas inilah yang membuatnya sangat berguna.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Sifat Kimia Seng$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Seng mudah melepaskan dua elektron membentuk ion Zn2+, membuatnya reaktif terhadap asam dan udara lembap. Namun lapisan tipis seng oksida yang terbentuk di permukaannya justru melindunginya dari korosi lanjutan — sifat yang disebut pasivasi. Titik lelehnya relatif rendah (419,5 C), sehingga mudah dicetak dan dipadukan dengan logam lain.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Galvanisasi: Perisai Anti Karat Besi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Kegunaan terbesar seng adalah galvanisasi — melapisi besi atau baja dengan lapisan seng untuk mencegah karat. Caranya: besi dicelupkan ke seng cair (hot-dip galvanizing). Seng yang lebih reaktif akan 'berkorban' teroksidasi lebih dulu, melindungi besi di bawahnya bahkan jika lapisan tergores. Prinsip perlindungan katodik inilah yang membuat tiang listrik, pagar, dan atap seng tahan puluhan tahun di cuaca ekstrem.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Paduan dan Kegunaan Lain$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Seng dipadukan dengan tembaga membentuk kuningan (brass) — bahan alat musik, keran, dan ornamen. Seng oksida dipakai dalam cat, karet ban, dan tabir surya. Dalam baterai, seng menjadi anoda pada baterai alkaline yang kita pakai sehari-hari di remote dan jam dinding.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Seng bagi Tubuh Manusia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Tubuh manusia membutuhkan seng dalam jumlah kecil namun vital: ia berperan dalam sistem kekebalan tubuh, penyembuhan luka, indra perasa dan penciuman, serta sintesis protein. Kekurangan seng dapat menyebabkan mudah sakit, luka lama sembuh, dan rambut rontok. Sumber alaminya antara lain daging merah, tiram, kacang-kacangan, dan biji-bijian. Seperti semua suplemen, konsumsi berlebih justru berbahaya — ikuti anjuran dokter atau ahli gizi.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Menjelaskan sifat-sifat magnet dan kutub magnet$txt$, $txt$Menggambarkan garis gaya magnet dan medan magnet$txt$, $txt$Menjelaskan cara membuat magnet$txt$, $txt$Menjelaskan prinsip elektromagnet dan penerapannya$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Sifat-Sifat Magnet$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Magnet adalah benda yang dapat menarik benda-benda dari besi, baja, nikel, dan kobalt. Setiap magnet memiliki dua kutub: kutub utara (U) dan kutub selatan (S). Sifat pentingnya: kutub senama tolak-menolak, kutub tidak senama tarik-menarik. Jika magnet dipotong, setiap potongan tetap memiliki dua kutub — kutub magnet tidak bisa dipisahkan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Medan Magnet dan Garis Gaya Magnet$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Di sekitar magnet terdapat medan magnet, yaitu daerah yang masih dipengaruhi gaya magnet. Garis gaya magnet adalah garis khayal yang menggambarkan arah medan: keluar dari kutub utara dan masuk ke kutub selatan. Garis-garis ini tidak pernah berpotongan, dan kerapatannya menunjukkan kuat lemahnya medan magnet di suatu titik.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Cara Membuat Magnet$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Menggosok: gosokkan magnet permanen searah pada batang besi berulang-ulang$txt$, $txt$Induksi: dekatkan besi pada magnet kuat tanpa menyentuh hingga besi menjadi magnet sementara$txt$, $txt$Elektromagnet: lilitkan kawat berarus listrik pada inti besi — magnetnya hilang saat arus diputus$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Elektromagnet dan Penerapannya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Elektromagnet adalah magnet buatan dari kumparan kawat berarus listrik. Kekuatannya bisa diatur dengan mengubah kuat arus atau jumlah lilitan. Penerapannya ada di mana-mana: bel listrik, relai, motor listrik, pengeras suara (speaker), dan crane pengangkat besi tua di tempat rongsokan. Bahkan kereta maglev melayang berkat tolak-menolak magnet yang kuat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Latihan: 1) Sebutkan tiga sifat magnet! 2) Sebuah magnet batang dipotong menjadi tiga bagian — berapa jumlah kutub seluruh potongan? 3) Jelaskan perbedaan magnet permanen dan elektromagnet! Kunci: 1) Menarik logam tertentu, berkutub dua, senama tolak-menolak; 2) Tiap potongan tetap 2 kutub, total 6 kutub; 3) Permanen sifatnya tetap, elektromagnet hanya saat dialiri arus dan kekuatannya dapat diatur.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Menjelaskan pengertian globalisasi dengan bahasa sendiri$txt$, $txt$Memberi contoh globalisasi dalam kehidupan sehari-hari$txt$, $txt$Menyebutkan dampak positif dan negatif globalisasi$txt$, $txt$Menunjukkan sikap bijak menghadapi globalisasi$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Globalisasi?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Globalisasi adalah proses mendunianya berbagai hal — barang, informasi, budaya, dan teknologi — sehingga batas antarnegara seolah menghilang. Contoh sederhananya: kamu bisa menonton kartun dari Jepang, memakai sepatu buatan Vietnam, dan video call dengan saudara di luar negeri, semua dari kamarmu. Itu semua terjadi karena globalisasi!$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Contoh Globalisasi di Sekitar Kita$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Makanan: fried chicken, pizza, dan sushi mudah ditemukan di Indonesia$txt$, $txt$Teknologi: HP yang kita pakai dibuat dari komponen berbagai negara$txt$, $txt$Budaya: lagu K-pop digemari anak Indonesia$txt$, $txt$Informasi: berita dari belahan dunia lain sampai dalam hitungan detik lewat internet$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Dampak Positif dan Negatif$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Positif: kemajuan teknologi sampai ke pelosok, pilihan barang lebih banyak, komunikasi mudah ke seluruh dunia$txt$, $txt$Negatif: budaya lokal bisa tergeser, produk dalam negeri kalah bersaing, hoaks menyebar sangat cepat$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Sikap Bijak Menghadapi Globalisasi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Globalisasi tidak bisa ditolak, tetapi bisa disikapi dengan bijak: ambil yang baik dan buang yang buruk. Tetap banggakan budaya Indonesia, cintai produk dalam negeri, selalu cek kebenaran berita sebelum menyebarkannya, dan gunakan teknologi untuk belajar hal-hal positif. Dengan begitu, kita menjadi warga dunia tanpa kehilangan jati diri sebagai anak Indonesia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Latihan: 1) Apa yang dimaksud globalisasi? 2) Sebutkan dua contohnya dalam kehidupan sehari-hari! 3) Sebutkan satu dampak positif dan satu dampak negatif! Kunci: 1) Proses mendunianya berbagai hal sehingga batas antarnegara seolah menghilang; 2) Menonton kartun Jepang, video call ke luar negeri; 3) Positif: komunikasi mudah — Negatif: hoaks cepat menyebar.$txt$));
